    <style>
        :root{--navy:#082d4d;--green:#0c9a73;--mint:#e9f8f3;--gold:#f4ae39;--text:#1a334b;--muted:#66788a;--line:#dbe6eb;--paper:#f6fafb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--text);font:16px/1.65 Arial,sans-serif}a{text-decoration:none;color:inherit}.wrap{width:min(1160px,calc(100% - 36px));margin:auto}.top{background:var(--navy);color:#dceaf3;font-size:13px}.top .wrap{min-height:38px;display:flex;align-items:center;justify-content:space-between}.top div:last-child{display:flex;gap:20px}.header{position:sticky;top:0;z-index:10;background:#fff;box-shadow:0 2px 13px #082d4d12}.nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:25px}.brand{display:flex;align-items:center;gap:11px;color:var(--navy);font-size:19px;font-weight:800}.brand img{width:49px;height:49px}.brand small{display:block;color:var(--green);font-size:11px}.links{display:flex;align-items:center;gap:23px;font-size:14px;font-weight:700}.links a:hover{color:var(--green)}.button{display:inline-flex;align-items:center;justify-content:center;padding:0 21px;min-height:45px;border:1px solid var(--green);border-radius:7px;background:var(--green);color:#fff;font-weight:800}.button:hover{background:#067756}.outline{background:transparent;border-color:#fff}.menu{display:none;border:0;background:transparent;font-size:26px;color:var(--navy)}.hero{min-height:590px;display:grid;align-items:center;color:#fff;background:linear-gradient(90deg,#082d4ded,#082d4da8,#082d4d42),url('/al_bg.png') center/cover}.hero-content{width:min(1160px,calc(100% - 36px));margin:auto}.tag{display:inline-block;padding:5px 13px;border:1px solid #ffffff75;border-radius:30px;background:#0c9a7350;color:#d7fff2;font-size:13px;font-weight:700}h1{max-width:700px;margin:16px 0;font-size:clamp(42px,6vw,74px);line-height:1.08}.hero p{max-width:590px;font-size:19px;color:#e4eef3}.actions{display:flex;gap:12px;flex-wrap:wrap}.quick{position:relative;margin-top:-45px}.quick-grid{display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden;border-radius:10px;box-shadow:0 17px 42px #082d4d2c}.quick a{padding:22px;color:#fff;background:var(--navy);border-right:1px solid #ffffff24}.quick a:nth-child(even){background:var(--green)}.quick b{display:block;font-size:17px}.quick span{font-size:13px;opacity:.86}section{padding:82px 0}.head{max-width:680px;margin:0 auto 40px;text-align:center}.eyebrow{margin:0 0 8px;color:var(--green);font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:1px}h2{margin:0;color:var(--navy);font-size:clamp(29px,4vw,43px);line-height:1.25}.muted{color:var(--muted)}.about{display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:center}.school-image{height:405px;border-radius:12px;background:linear-gradient(#082d4d28,#082d4d28),url('/afghanistan_school.png') center/cover;box-shadow:18px 18px var(--mint)}.checks{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0;list-style:none;font-weight:700}.checks li:before{content:'✓';display:inline-grid;place-items:center;width:21px;height:21px;margin-right:8px;border-radius:50%;background:var(--green);color:#fff;font-size:12px}.stats,.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat{padding:15px;text-align:center;border:1px solid var(--line);border-radius:8px}.stat b{display:block;color:var(--green);font-size:27px}.stat span{font-size:12px;color:var(--muted);font-weight:700}.programs,.contact{background:var(--paper)}.cards{grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:27px;border:1px solid var(--line);border-radius:10px;background:#fff}.card:hover{transform:translateY(-4px);box-shadow:0 16px 30px #082d4d15}.icon{display:grid;place-items:center;width:52px;height:52px;margin-bottom:17px;border-radius:10px;background:var(--mint);color:var(--green);font-size:25px}.card h3{margin:0 0 7px;color:var(--navy)}.card p{margin:0;color:var(--muted);font-size:14px}.admission{color:#fff;background:linear-gradient(120deg,#082d4d,#125276)}.admission-grid,.contact-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:48px;align-items:center}.admission h2{color:#fff}.steps{display:grid;gap:12px}.step{padding:13px 15px;border-radius:8px;background:#ffffff12}.step b{display:inline-grid;place-items:center;width:30px;height:30px;margin-right:10px;border-radius:50%;background:var(--gold);color:var(--navy)}.admission-card,.portal{padding:29px;border-radius:10px;background:#fff;color:var(--text)}.admission-card h3{margin-top:0;color:var(--navy)}.news{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.news article{overflow:hidden;border:1px solid var(--line);border-radius:10px}.news-image{height:175px;background:linear-gradient(#082d4d27,#082d4d27),url('/afghanistan_school.png') center/cover}.news article:first-child .news-image{background-image:linear-gradient(#082d4d27,#082d4d27),url('/al_bg.png')}.news div:last-child{padding:20px}.news time{color:var(--green);font-size:12px;font-weight:800}.news h3{margin:7px 0;color:var(--navy)}.news p{margin:0;color:var(--muted);font-size:14px}.contact-list{display:grid;gap:12px;margin-top:23px}.contact-item{padding:14px 16px;border:1px solid var(--line);border-radius:8px;background:#fff}.contact-item b,.contact-item span{display:block}.contact-item span{font-size:13px;color:var(--muted)}.portal{background:var(--green);color:#fff}.portal h3{margin-top:0;font-size:25px}.portal p{color:#dffff4}.portal a{display:block;margin-top:10px;padding:11px 14px;border-radius:6px;background:#ffffff20;font-weight:700}.footer{padding:28px 0;background:#062741;color:#c2d3df;font-size:13px}.footer .wrap{display:flex;justify-content:space-between}.footer b{color:#fff}@media(max-width:820px){.menu{display:block}.links{position:absolute;top:78px;left:0;right:0;display:none;flex-direction:column;align-items:stretch;gap:0;padding:15px 18px 20px;background:#fff;border-top:1px solid var(--line)}.links.open{display:flex}.links a{padding:9px 0}.quick-grid,.cards,.news{grid-template-columns:repeat(2,1fr)}.about,.admission-grid,.contact-grid{grid-template-columns:1fr}.school-image{order:2}.news article:first-child{grid-column:span 2}}@media(max-width:520px){.top{display:none}.wrap,.hero-content{width:min(100% - 28px,1160px)}.nav{height:70px}.links{top:70px}.brand{font-size:16px}.hero{min-height:540px}section{padding:60px 0}.quick{margin-top:-20px}.quick-grid,.cards,.news,.stats,.checks{grid-template-columns:1fr}.news article:first-child{grid-column:auto}.footer .wrap{display:block}}
    </style>
